mapper.sql:
FROM product_spu p JOIN category c ON c.id=p.category_id WHERE p.status='ON_SALE' AND c.enabled=1 AND EXISTS (SELECT 1 FROM product_sku s WHERE s.product_id=p.id AND s.enabled=1)
AND p.category_id=#{query.categoryId}
AND (LOCATE(#{query.keyword},p.name) > 0 OR LOCATE(#{query.keyword},p.brand) > 0)

mapper.select:
SELECT CAST(p.id AS CHAR) AS productId, p.name, p.image_url AS imageUrl, (SELECT MIN(s.price_fen) FROM product_sku s WHERE s.product_id=p.id AND s.enabled=1) AS minPriceFen, p.status
ORDER BY minPriceFen ASC, p.id DESC ORDER BY minPriceFen DESC, p.id DESC ORDER BY p.id DESC
LIMIT #{query.size} OFFSET #{offset}
